def _parse_multirange(value: str) -> tuple[tuple[int, int], ...]:
    return tuple((int(start), int(end)) for start, end in re.findall(r"\[(\d+),(\d+)\)", value))


UNSAFE_CODEPOINT_RANGES: Final = _parse_multirange(UNSAFE_CODEPOINT_MULTIRANGE)
MARK_CODEPOINT_RANGES: Final = _parse_multirange(MARK_CODEPOINT_MULTIRANGE)
_UNSAFE_STARTS: Final = tuple(start for start, _ in UNSAFE_CODEPOINT_RANGES)
_MARK_STARTS: Final = tuple(start for start, _ in MARK_CODEPOINT_RANGES)


def _contains(
    codepoint: int,
    ranges: tuple[tuple[int, int], ...],
    starts: tuple[int, ...],
) -> bool:
    index = bisect.bisect_right(starts, codepoint) - 1
    return index >= 0 and codepoint < ranges[index][1]


def is_safe_identifier(value: str, maximum_octets: int) -> bool:
    """Apply the frozen v1 identifier contract without runtime Unicode data."""
    try:
        encoded = value.encode("utf-8")
    except UnicodeEncodeError:
        return False
    if (
        maximum_octets < 1
        or not value
        or value != value.strip(" ")
        or len(encoded) > maximum_octets
    ):
        return False

    has_visible_character = False
    for character in value:
        codepoint = ord(character)
        if _contains(codepoint, UNSAFE_CODEPOINT_RANGES, _UNSAFE_STARTS):
            return False
        if codepoint != 0x20 and not _contains(codepoint, MARK_CODEPOINT_RANGES, _MARK_STARTS):
            has_visible_character = True
    return has_visible_character


CREATE_SAFE_IDENTIFIER_FUNCTION_SQL: Final = f"""
CREATE OR REPLACE FUNCTION is_safe_identifier(value text, maximum_octets integer)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
STRICT
PARALLEL SAFE
AS $function$
DECLARE
    character_index integer;
    current_character text;
    codepoint integer;
    has_visible_character boolean := false;
    unsafe_codepoints constant int4multirange :=
        '{UNSAFE_CODEPOINT_MULTIRANGE}'::int4multirange;
    mark_codepoints constant int4multirange :=
        '{MARK_CODEPOINT_MULTIRANGE}'::int4multirange;
BEGIN
    IF pg_catalog.getdatabaseencoding() <> 'UTF8'
       OR maximum_octets < 1
       OR value = ''
       OR value <> pg_catalog.btrim(value)
       OR pg_catalog.octet_length(value) > maximum_octets THEN
        RETURN false;
    END IF;
    FOR character_index IN 1..pg_catalog.char_length(value) LOOP
        current_character := pg_catalog.substr(value, character_index, 1);
        codepoint := pg_catalog.ascii(current_character);
        IF unsafe_codepoints @> codepoint THEN
            RETURN false;
        END IF;
        IF codepoint <> 32 AND NOT (mark_codepoints @> codepoint) THEN
            has_visible_character := true;
        END IF;
    END LOOP;
    RETURN has_visible_character;
END;
$function$
"""

DROP_SAFE_IDENTIFIER_FUNCTION_SQL: Final = (
    "DROP FUNCTION IF EXISTS is_safe_identifier(text, integer)"
)

CREATE_EVIDENCE_TRUNCATE_FUNCTION_SQL: Final = """
CREATE OR REPLACE FUNCTION prevent_evaluation_evidence_truncate()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'evaluation evidence cannot be truncated'
        USING ERRCODE = '55000';
END;
$function$
"""

DROP_EVIDENCE_TRUNCATE_FUNCTION_SQL: Final = (
    "DROP FUNCTION IF EXISTS prevent_evaluation_evidence_truncate()"
)
